/// <summary>
/// NDX_MultipleSelect_Chain
/// </summary>
class NDX_MultipleSelect_Chain extends NDX_MultipleSelect
{
    NDXMultipleS_smmBusRelChainGroup     nDX_SelectionTmp;        // Vorlagedaten für die Selektion der bereits markierten Datensätze
    smmChainId              companyChainId;
    smmBusRelChainGroup     smmBusRelChainGroup;
}

Method.Source:
void closedSelectForm()
{
    FormDataSource  formDatasource;
    int             i, nBis;
    tableId         tableId;
    ;

    nBis = selectForm.dataSourceCount();
    for (i = 1; i <= nBis; i++)
    {
        formDataSource  = selectForm.dataSource(i);
        tableId         = formDataSource.table();
        if (tableId == tablenum(NDXMultipleS_smmBusRelChainGroup))
        {
            nDX_SelectionTmp.data(formDatasource.cursor());
            break;
        }
    }
}
